// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { signIn, openHighlightsLibrary, applyColorFilter } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(156000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // Collect uncaught page errors so a crash on the new page cannot pass silently.
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    // Credential(s) read from the environment — never recorded into this file. Set these before running.
    if (process.env.SKYRAMP_UI_PASSWORD === undefined) {
        throw new Error("SKYRAMP_UI_PASSWORD is not set: this test replays a login and needs that credential in the environment");
    }
    const loginPassword = process.env.SKYRAMP_UI_PASSWORD ?? "";

    await page.goto(`${baseUrl}/login`);
    await signIn(page, "testbot-admin", loginPassword);

    // The Highlights entry the PR adds to the sidebar opens the new library page.
    await openHighlightsLibrary(page);
    await expect(page).toHaveURL(`${baseUrl}/highlights`);

    // The page mounts and resolves its new translation keys rather than showing raw key names.
    await expect(page.getByTestId("highlights-empty")).toBeVisible();
    await expect(page.getByTestId("highlights-empty")).toContainText("No highlights yet");
    await expect(page.getByTestId("highlights-empty")).toContainText("Highlight a passage while you read and it shows up here.");
    await expect(page.getByText("Highlight a passage while you")).toContainText("Highlight a passage while you read and it shows up here.");

    // The colour filter offers exactly the four colours the API enum allows, plus All.
    await expect(page.getByTestId("highlight-color-all")).toBeVisible();
    await expect(page.getByTestId("highlight-color-yellow")).toBeVisible();
    await expect(page.getByTestId("highlight-color-green")).toBeVisible();
    await expect(page.getByTestId("highlight-color-blue")).toBeVisible();
    await expect(page.getByTestId("highlight-color-red")).toBeVisible();
    await expect(page.getByTestId("highlight-search")).toBeVisible();

    // Filtering by a colour keeps the page rendering rather than erroring out.
    await applyColorFilter(page, "highlight-color-yellow");
    await expect(page.getByTestId("highlights-empty")).toBeVisible();
    await expect(page.getByTestId("highlights-empty")).toContainText("No highlights yet");

    expect(pageErrors, 'the Highlights page raised no uncaught errors').toEqual([]);
});
